import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8

// Tiled shared-memory SGEMM: C(MxN) = A(MxK) * B(KxN)
// Each block computes a 128x128 tile of C; each of the 256 threads computes an 8x8 sub-tile.
__global__ void matmul_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K,
                              bool vec_ok) {
    __shared__ float As[BK][BM];
    __shared__ float Bs[BK][BN];

    const int tid = threadIdx.x;
    const int bm = blockIdx.y * BM;
    const int bn = blockIdx.x * BN;

    // compute-tile coordinates of this thread
    const int tx = tid % (BN / TN);  // 0..15
    const int ty = tid / (BN / TN);  // 0..15

    // loader indices for the A tile (BM x BK), float4 loads: 4 threads/row, 64 rows/pass
    const int aRow = tid / (BK / 4);
    const int aCol = (tid % (BK / 4)) * 4;
    // loader indices for the B tile (BK x BN), float4 loads: 32 threads/row, 8 rows/pass
    const int bRow = tid / (BN / 4);
    const int bCol = (tid % (BN / 4)) * 4;

    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            acc[i][j] = 0.0f;

    for (int k0 = 0; k0 < K; k0 += BK) {
        // ---- Load A tile into As (transposed layout) ----
        #pragma unroll
        for (int r = 0; r < BM; r += 64) {
            int gRow = bm + aRow + r;
            int gCol = k0 + aCol;
            float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
            if (gRow < M) {
                const float* ptr = A + (long)gRow * K + gCol;
                if (vec_ok && gCol + 3 < K) {
                    v = *reinterpret_cast<const float4*>(ptr);
                } else {
                    v.x = (gCol + 0 < K) ? ptr[0] : 0.f;
                    v.y = (gCol + 1 < K) ? ptr[1] : 0.f;
                    v.z = (gCol + 2 < K) ? ptr[2] : 0.f;
                    v.w = (gCol + 3 < K) ? ptr[3] : 0.f;
                }
            }
            As[aCol + 0][aRow + r] = v.x;
            As[aCol + 1][aRow + r] = v.y;
            As[aCol + 2][aRow + r] = v.z;
            As[aCol + 3][aRow + r] = v.w;
        }
        // ---- Load B tile into Bs ----
        #pragma unroll
        for (int r = 0; r < BK; r += 8) {
            int gRow = k0 + bRow + r;
            int gCol = bn + bCol;
            float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
            if (gRow < K) {
                const float* ptr = B + (long)gRow * N + gCol;
                if (vec_ok && gCol + 3 < N) {
                    v = *reinterpret_cast<const float4*>(ptr);
                } else {
                    v.x = (gCol + 0 < N) ? ptr[0] : 0.f;
                    v.y = (gCol + 1 < N) ? ptr[1] : 0.f;
                    v.z = (gCol + 2 < N) ? ptr[2] : 0.f;
                    v.w = (gCol + 3 < N) ? ptr[3] : 0.f;
                }
            }
            *reinterpret_cast<float4*>(&Bs[bRow + r][bCol]) = v;
        }
        __syncthreads();

        // ---- Compute on the resident tiles ----
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            float rA[TM];
            float rB[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                rA[i] = As[k][ty * TM + i];
            #pragma unroll
            for (int j = 0; j < TN; j += 4)
                *reinterpret_cast<float4*>(&rB[j]) =
                    *reinterpret_cast<const float4*>(&Bs[k][tx * TN + j]);
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += rA[i] * rB[j];
        }
        __syncthreads();
    }

    // ---- Write results ----
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int gRow = bm + ty * TM + i;
        if (gRow >= M) break;
        int gCol = bn + tx * TN;
        float* ptr = C + (long)gRow * N + gCol;
        if (vec_ok && gCol + TN <= N) {
            #pragma unroll
            for (int j = 0; j < TN; j += 4)
                *reinterpret_cast<float4*>(ptr + j) =
                    *reinterpret_cast<const float4*>(&acc[i][j]);
        } else {
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                if (gCol + j < N) ptr[j] = acc[i][j];
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    const int M = (int)Ac.size(0);
    const int K = (int)Ac.size(1);
    const int N = (int)Bc.size(1);

    auto C = torch::empty({M, N}, Ac.options());

    bool vec_ok = (K % 4 == 0) && (N % 4 == 0);
    dim3 block(256);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_kernel<<<grid, block, 0, stream>>>(
        Ac.data_ptr<float>(), Bc.data_ptr<float>(), C.data_ptr<float>(),
        M, N, K, vec_ok);
    return C;
}
"""

cpp_src = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

_mod = load_inline(
    name="custom_matmul_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled shared-memory CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if A.is_cuda and B.is_cuda and A.dtype == torch.float32 and B.dtype == torch.float32:
            return _mod.matmul_cuda(A, B)
        return torch.matmul(A, B)

